class Enumeration {
  constructor(list) {
    this.list = list;
  }
}

class Repeatable {
  constructor(list) {
    this.list = list;
  }
}

class Sequence {
  constructor(list) {
    this.list = list;
  }

  get(depth) {
    return this.list[depth];
  }
}

